pair A,B,C,D,I;
A=(0,0);
B=(0,5);
C=(7,7);
I=(7,5);
D=(7,0);
draw(A--B--C--D--cycle);
draw(B--I);
label("$A$",A,W);
label("$B$",B,W);
label("$C$",C,E);
label("$E$",I,E);
label("$D$",D,E);
[/asy]

